<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue';
const props=defineProps<{api:(path:string,method?:string,body?:unknown)=>Promise<any>}>();
const emit=defineEmits<{openTask:[id:string]}>();
const profile=ref<any>(),revision=ref(0),control=ref<any>(),hard=ref<any>(),saved=ref(''),message=ref(''),busy=ref(false),ack=ref(false),riskAck=ref(false),newAnalysisAck=ref(false),showProfile=ref(false);
const candidates=ref<any[]>([]),selected=ref<any>(),runs=ref<any[]>([]),run=ref<any>(),selection=ref<any>(),filter=ref('active'),page=ref(1),cooldowns=ref<any[]>([]);
const repositoryUrl=ref('');
const languages=ref(''),preferred=ref(''),excludedLabels=ref('');let disposed=false,timer:ReturnType<typeof setTimeout>|undefined;
const dirty=computed(()=>profile.value&&(JSON.stringify(profile.value)!==saved.value||languages.value!==profile.value.languages.join(', ')||preferred.value!==profile.value.preferredLabels.join(', ')||excludedLabels.value!==profile.value.excludedLabels.join(', ')));
const split=(v:string)=>v.split(/[,，]/).map(x=>x.trim()).filter(Boolean);
const date=(n:number)=>n?new Date(n).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'尚未检查';
const bounds=[['maxRepos','每轮仓库'],['maxIssues','每轮 Issue'],['repoPages','仓库搜索页'],['issuePages','每仓库 Issue 页'],['httpAttempts','每轮 HTTP'],['dailyHttp','每日发现 HTTP'],['maxBytes','每轮字节'],['timeoutMs','请求超时 ms'],['maxEvaluations','每轮评估'],['evaluationTokens','每轮评估 Token'],['dailyModelCalls','每日模型调用'],['dailyModelTokens','每日模型 Token']];
async function loadProfile(){const result=await props.api('admin/discovery/profile');if(disposed)return;profile.value=result.profile;revision.value=result.revision;control.value=result.control;hard.value=result.hardLimits;cooldowns.value=result.cooldowns;saved.value=JSON.stringify(result.profile);languages.value=result.profile.languages.join(', ');preferred.value=result.profile.preferredLabels.join(', ');excludedLabels.value=result.profile.excludedLabels.join(', ');if(!result.revision)showProfile.value=true;}
async function refresh(){const [list,history,current]=await Promise.all([props.api(`admin/discovery/candidates?page=${page.value}&filter=${filter.value}`),props.api('admin/discovery/runs'),props.api('admin/discovery/profile')]);if(disposed)return;candidates.value=list.items;runs.value=history.items;control.value=current.control;cooldowns.value=current.cooldowns;if(run.value)run.value=await props.api('admin/discovery/runs/'+run.value.id);else if(runs.value[0])run.value=await props.api('admin/discovery/runs/'+runs.value[0].id);if(selected.value)selected.value=await props.api('admin/discovery/candidates/'+selected.value.issue_id);if(selection.value){const next=await props.api('admin/discovery/selections/'+selection.value.id);if(next.hash!==selection.value.hash)riskAck.value=false;selection.value=next;}}
async function poll(){try{await refresh();}catch(e){if(!disposed)message.value=(e as Error).message;}if(!disposed)timer=setTimeout(poll,3000);}
onMounted(async()=>{try{await loadProfile();await poll();}catch(e){message.value=(e as Error).message;}});onUnmounted(()=>{disposed=true;clearTimeout(timer);});
async function perform(fn:()=>Promise<void>){busy.value=true;message.value='';try{await fn();}catch(e){message.value=(e as Error).message;}finally{busy.value=false;}}
async function save(){await perform(async()=>{const value={...profile.value,languages:split(languages.value),preferredLabels:split(preferred.value),excludedLabels:split(excludedLabels.value)};await props.api('admin/discovery/profile','PUT',{profile:value,expectedRevision:revision.value,acknowledgeCost:ack.value});await loadProfile();await refresh();ack.value=false;showProfile.value=false;message.value='画像已保存。保存本身不扫描、不调用模型。';});}
async function scan(){await perform(async()=>{run.value=await props.api('admin/discovery/runs','POST',{requestKey:crypto.randomUUID(),revision:revision.value});await refresh();message.value='本轮已加入统一队列；不会自动创建分析。';});}
async function inspect(c:any){await perform(async()=>{selected.value=await props.api('admin/discovery/candidates/'+c.issue_id);selection.value=selected.value.selections[0]?await props.api('admin/discovery/selections/'+selected.value.selections[0].id):undefined;riskAck.value=false;});}
async function action(c:any,name:string){await perform(async()=>{const result=await props.api(`admin/discovery/candidates/${c.issue_id}/actions`,'POST',{action:name,expectedVersion:c.version});if(selected.value?.issue_id===c.issue_id)selected.value=result;await refresh();});}
async function exclude(c:any){await perform(async()=>{const current=await props.api('admin/discovery/profile');current.profile.excludedRepos=[...new Set([...current.profile.excludedRepos,c.repo_id])];await props.api('admin/discovery/profile','PUT',{profile:current.profile,expectedRevision:current.revision,acknowledgeCost:false});await loadProfile();await refresh();message.value='已排除该稳定仓库 ID；现有分析需在任务区另行取消。';});}
async function resolveExclusion(){await perform(async()=>{await props.api('admin/discovery/exclusions/resolve','POST',{url:repositoryUrl.value,expectedRevision:revision.value});repositoryUrl.value='';await loadProfile();await refresh();message.value='仓库名称已解析为稳定 ID 并排除。';});}
async function unexclude(id:number){profile.value.excludedRepos=profile.value.excludedRepos.filter((x:number)=>x!==id);}
async function selectAnalysis(confirmNew=false){await perform(async()=>{selection.value=await props.api(`admin/discovery/candidates/${selected.value.issue_id}/select`,'POST',{requestKey:crypto.randomUUID(),revision:revision.value,confirmNewAnalysis:confirmNew});riskAck.value=false;newAnalysisAck.value=false;await refresh();});}
async function recheck(){await perform(async()=>{selection.value=await props.api(`admin/discovery/selections/${selection.value.id}/refresh`,'POST',{});riskAck.value=false;await refresh();});}
async function confirm(){await perform(async()=>{selection.value=await props.api(`admin/discovery/selections/${selection.value.id}/confirm`,'POST',{hash:selection.value.hash,acknowledgeCost:true});riskAck.value=false;await refresh();message.value='已打开关联分析入口。新建候选任务在开始前再次复核；已有任务保持原流程。';});}
async function reevaluate(){await perform(async()=>{run.value=await props.api(`admin/discovery/candidates/${selected.value.issue_id}/reevaluate`,'POST',{requestKey:crypto.randomUUID(),revision:revision.value,acknowledgeCost:true});ack.value=false;await refresh();});}
async function cancel(){await perform(async()=>{await props.api(`admin/discovery/runs/${run.value.id}/cancel`,'POST',{});await refresh();});}
</script>
<template>
  <section class="content discovery-workspace">
    <p class="eyebrow">DISCOVERY / 从你的技术方向出发</p>
    <div class="title-row"><div><h1>发现下一次贡献</h1><p class="muted">有限范围找线索，由你决定是否深入。只读 GitHub，不运行目标代码。</p></div><button class="primary" :disabled="busy||!revision||dirty" @click="scan">立即发现 →</button></div>
    <p v-if="message" role="status" class="notice">{{message}}</p>
    <section v-if="profile" class="profile-strip panel"><div><strong>技术画像 v{{revision}}</strong><p>{{profile.languages.join(' / ')}} · {{profile.requirePreferred?'必须匹配标签':'标签仅作偏好'}} · 模型评估{{control.evaluation_enabled?'已开启（可能持续计费）':'关闭'}}</p><p class="muted">定时{{control.enabled?`每日 UTC ${String(profile.utcHour).padStart(2,'0')}:00 / 北京时间 ${String((profile.utcHour+8)%24).padStart(2,'0')}:00`:'未启用'}} · {{control.next_due_at?'下次 '+date(control.next_due_at):'不会自动扫描'}} · 错过跳过 {{control.missed_count}} 次</p></div><button @click="showProfile=!showProfile">{{showProfile?'收起画像':'编辑技术画像'}}</button></section>
    <form v-if="showProfile&&profile" class="panel profile-editor" @submit.prevent="save"><h2>我的技术画像</h2><div class="fields"><label>偏好语言（逗号分隔）<input v-model="languages" required maxlength="160"></label><label>偏好标签（逗号分隔）<input v-model="preferred" maxlength="1600"></label><label>排除标签（逗号分隔）<input v-model="excludedLabels" maxlength="1600"></label><label>仓库活跃天数<input v-model.number="profile.repoActiveDays" type="number" min="1" max="730" required></label><label>Issue 更新天数<input v-model.number="profile.issueActiveDays" type="number" min="1" max="365" required></label><label>Star 最小值<input v-model.number="profile.minStars" type="number" min="0" max="10000000" required></label><label>Star 最大值<input v-model.number="profile.maxStars" type="number" min="0" max="10000000" required></label><label>每日 UTC 整点<input v-model.number="profile.utcHour" type="number" min="0" max="23" required></label></div>
      <div class="discovery-checks"><label><input v-model="profile.requirePreferred" type="checkbox">必须匹配偏好标签</label><label><input v-model="profile.filterStars" type="checkbox">启用 Star 范围</label><label><input v-model="profile.requireUnassigned" type="checkbox">仅无人认领</label><label><input v-model="profile.scheduleEnabled" type="checkbox">开启每日定时发现</label><label><input v-model="profile.evaluationEnabled" type="checkbox">开启少量模型评估（定时也可能计费）</label></div>
      <p>排除仓库 ID：<span v-if="!profile.excludedRepos.length">无</span><button v-for="id in profile.excludedRepos" :key="id" type="button" @click="unexclude(id)">{{id}} × 移除</button></p>
      <label>排除仓库链接<input v-model="repositoryUrl" type="url" placeholder="https://github.com/owner/repo"></label><button type="button" :disabled="busy||!revision||dirty||!repositoryUrl" @click="resolveExclusion">解析并排除公开仓库</button><details><summary>每轮与每日资源限额</summary><div class="fields"><label v-for="[key,label] in bounds" :key="key">{{label}}<input v-model.number="profile[key]" type="number" min="1" :max="hard[key]" required></label></div></details>
      <label class="cost-line"><input v-model="ack" type="checkbox">我确认：开启模型评估后，手动和定时发现可能持续产生模型费用。</label>
      <div class="action-row"><button class="primary" :disabled="busy">保存画像</button><button type="button" :disabled="busy" @click="loadProfile">重新加载保存版本</button></div><p class="muted">收藏/忽略不会被重扫清除。关闭定时不等于取消手动轮次；忽略候选不会取消已有分析。</p>
    </form>
    <p v-if="dirty" class="notice">存在未保存画像编辑，请保存后再发起发现。</p>
    <p v-for="c in cooldowns" :key="c.resource" class="notice">GitHub {{c.resource}} 冷却至 {{date(c.not_before)}} · {{c.reason}}</p>
    <section v-if="run" class="run-strip panel" aria-label="发现运行详情"><div class="section-heading"><h2>本轮 {{run.status}} <small>{{run.data_source}}</small></h2><button v-if="['QUEUED','RUNNING'].includes(run.status)" :disabled="busy" @click="cancel">取消本轮</button></div><p>仓库 {{run.counts.repos||0}} · Issue {{run.counts.issues||0}} · 匹配 {{run.counts.matched||0}} · HTTP {{run.http.attempts}} 次 · {{run.http.bytes}} 字节</p><p class="muted">{{run.reason||'仅表示本轮已读取范围，搜索结果可能延迟或遗漏。'}} · 画像 v{{run.revision}} · {{date(run.created_at)}}</p><p v-if="run.counts.evaluationReason&&run.counts.evaluationReason!=='NOT_RUN'" class="muted">模型评估：{{run.counts.evaluationReason}}</p><details><summary>最近轮次（最多 20 条）</summary><button v-for="r in runs" :key="r.id" type="button" @click="perform(async()=>{run=await api('admin/discovery/runs/'+r.id)})">{{r.trigger}} · {{r.status}} · {{date(r.created_at)}}</button></details></section>
    <div class="candidate-toolbar"><h2>候选线索 <small>每页最多 20 条</small></h2><label>候选筛选<select v-model="filter" @change="page=1;perform(refresh)"><option value="active">推荐候选</option><option value="all">全部候选</option><option value="ignored">已忽略</option></select></label><button :disabled="busy" @click="perform(refresh)">刷新候选</button></div>
    <div class="candidate-layout"><section class="candidate-list" aria-label="发现候选"><p v-if="!candidates.length" class="empty-state">这里还没有候选。保存画像并立即发现，或调整筛选查看已忽略的线索；“全部候选”包含已关联分析的记录。</p><article v-for="c in candidates" :key="c.issue_id" class="candidate-card" :class="{chosen:selected?.issue_id===c.issue_id}"><button class="candidate-title" @click="inspect(c)"><small>{{c.data.repo.name}} · #{{c.number}} · {{c.data.source}}</small><strong>{{c.title}}</strong></button><p>{{c.data.reasons[0]}} · {{c.data.preferred.length?'命中偏好标签':'标签未命中偏好'}}</p><p class="muted">{{c.remote_state}} · {{c.visibility}} · {{c.favorite?'已收藏':'未收藏'}} · {{c.needsRecheck?'需重新匹配/复核':'状态已检查'}}</p><div class="action-row"><button :disabled="busy" @click="action(c,c.favorite?'unfavorite':'favorite')">{{c.favorite?'取消收藏':'收藏'}}</button><button :disabled="busy" @click="action(c,c.visibility==='IGNORED'?'enable':'ignore')">{{c.visibility==='IGNORED'?'重新启用':'忽略'}}</button><button :disabled="busy" @click="exclude(c)">排除仓库</button></div></article><div class="action-row"><button :disabled="page===1||busy" @click="page--;perform(refresh)">上一页</button><span>第 {{page}} 页</span><button :disabled="candidates.length<20||busy" @click="page++;perform(refresh)">下一页</button></div></section>
    <section v-if="selected" class="panel candidate-detail" aria-label="候选详情"><p class="eyebrow">RULE FACTS / 匹配事实</p><h2>{{selected.title}}</h2><a :href="selected.url" target="_blank" rel="noopener noreferrer">查看 GitHub 来源 ↗</a><p>稳定 Issue ID {{selected.issue_id}} · 仓库 ID {{selected.repo_id}} · 画像 v{{selected.matched_revision}}</p><ul><li v-for="reason in selected.data.reasons" :key="reason">{{reason}}</li></ul><p class="muted">首次 {{date(selected.first_seen)}}<br>最近发现 {{date(selected.last_seen)}}<br>状态检查 {{date(selected.checked_at)}}</p><pre>{{selected.body}}</pre>
      <h3>模型意见（与规则事实分开）</h3><p v-if="!selected.evaluations.length" class="muted">NOT_RUN · 尚无模型评估。规则候选可独立使用。</p><div v-for="(e,index) in selected.evaluations" :key="index" class="evaluation"><strong>{{e.status}} · 用量 {{e.usage_state}}</strong><pre>{{e.content?JSON.stringify(JSON.parse(e.content),null,2):e.error_code||'没有模型意见'}}</pre></div>
      <label v-if="profile.evaluationEnabled" class="cost-line"><input v-model="ack" type="checkbox">我确认重新评估可能计费。</label><button v-if="profile.evaluationEnabled" :disabled="busy||!ack" @click="reevaluate">主动重新评估</button>
      <div class="recheck-section"><h3>进入分析前，先复核来源</h3><p class="muted">只检查元信息，无需模型配置。不会自动读取源码或付费分析。</p><button :disabled="busy||selected.visibility==='IGNORED'||selected.excluded" @click="selectAnalysis(false)">选择并复核来源</button>
        <template v-if="selection"><p>{{selection.status}} · {{selection.recheck_status}}</p><p v-if="selection.error_code" class="notice">{{selection.error_code}}</p><template v-if="selection.content"><p class="notice">{{selection.content.notice}}</p><p>关联 PR：{{selection.content.prs.length}} · 完整性 {{selection.content.complete?'本次有界检查完成':'UNKNOWN / 不完整'}}</p><p v-for="pr in selection.content.prs" :key="pr.id">{{pr.repo}} #{{pr.number}} · {{pr.state}} · {{pr.merged?'已合并':'未合并'}}</p><small>复核 hash {{selection.hash}} · 五分钟有效</small><label class="cost-line"><input v-model="riskAck" type="checkbox">我已核对重复修复风险，确认开始深入分析可能计费。</label><button class="primary" :disabled="busy||!riskAck||selection.recheck_status==='BLOCKED'||selection.status==='ANALYSIS_QUEUED'" @click="confirm">开始深入分析（可能计费）</button></template><label v-if="selection.task_id" class="cost-line"><input v-model="newAnalysisAck" type="checkbox">我理解新建选择可能产生重复分析与新费用，已有任务不受新配置影响。</label><button v-if="selection.task_id" :disabled="busy||!newAnalysisAck" @click="selectAnalysis(true)">新建选择并重新复核</button><div class="action-row"><button :disabled="busy||selection.status==='ANALYSIS_QUEUED'" @click="recheck">重新复核来源</button><button v-if="selection.task_id" @click="emit('openTask',selection.task_id)">打开关联分析任务 →</button></div></template>
      </div>
    </section><section v-else class="panel candidate-detail empty-detail"><p class="eyebrow">HUMAN IN THE LOOP</p><h2>先看线索，再决定。</h2><p class="muted">点击候选查看匹配依据、疑点与来源。公开仓库里的一个问题，只是贡献的起点。</p></section></div>
  </section>
</template>
<style scoped>
.discovery-workspace{max-width:1400px}.profile-strip{display:flex;justify-content:space-between;gap:24px;align-items:center;background:#eaf5ff}.profile-strip p{margin:7px 0;font-size:13px}.profile-editor{margin:20px 0}.profile-editor .fields{margin:20px 0}.discovery-checks{display:flex;flex-wrap:wrap;gap:16px;margin:20px 0}.discovery-checks label,.cost-line{display:flex;align-items:flex-start;gap:8px;font-size:13px}.discovery-checks input,.cost-line input{width:16px;height:16px;flex-shrink:0;margin:0}.cost-line{margin:20px 0;line-height:1.7}.run-strip{margin:22px 0;border-left:3px solid #62a7d5}.run-strip h2{font-size:16px}.run-strip small{color:#617e96;font-size:11px}.run-strip details button{display:block;margin:8px 0}.candidate-toolbar{display:flex;align-items:center;gap:18px;margin:28px 0 16px;flex-wrap:wrap}.candidate-toolbar h2{margin-right:auto;font-size:20px}.candidate-toolbar small{font-size:11px;color:#6c879c}.candidate-toolbar label{display:flex;gap:10px;align-items:center;font-size:13px}.candidate-toolbar select{padding:8px;border:1px solid #bdd7e9;background:white;border-radius:6px;color:#315574}.candidate-layout{display:grid;grid-template-columns:minmax(280px,.9fr) minmax(320px,1.1fr);gap:24px;align-items:start}.candidate-card{background:white;border:1px solid #d8e7f2;padding:20px;border-radius:10px;margin-bottom:14px}.candidate-card.chosen{border-color:#489bd1;box-shadow:0 0 0 2px #dceffc}.candidate-title{display:flex;flex-direction:column;gap:10px;background:none;border:0;padding:0;text-align:left;box-shadow:none;max-width:100%;overflow-wrap:anywhere}.candidate-title small{font-size:11px;color:#65829b;letter-spacing:.025em}.candidate-title strong{font-size:17px;line-height:1.6;color:#1d4262}.candidate-card p{font-size:12px;line-height:1.7}.candidate-card .action-row{gap:8px}.candidate-card .action-row button{padding:7px 10px;font-size:12px}.candidate-detail{position:sticky;top:24px;overflow-wrap:anywhere;min-width:0}.candidate-detail h2{font-size:20px;line-height:1.6}.candidate-detail h3{font-size:15px;margin-top:24px}.candidate-detail p,.candidate-detail li{font-size:13px;line-height:1.8}.candidate-detail pre{white-space:pre-wrap;overflow-wrap:anywhere;font-family:inherit;font-size:12px;line-height:1.8;background:#f0f7fc;padding:14px;border-radius:6px;max-height:280px;overflow:auto}.candidate-detail small{display:block;font-size:11px;overflow-wrap:anywhere}.recheck-section{margin-top:26px;padding-top:18px;border-top:1px solid #dce9f3}.empty-detail{min-height:260px;background:#f9fcff}.empty-state{padding:24px;color:#637e94;line-height:1.9}.evaluation{padding-block:10px;border-bottom:1px solid #e1edf5}.evaluation strong{font-size:12px}@media(max-width:1100px){.candidate-layout{grid-template-columns:1fr}.candidate-detail{position:static}.profile-strip{align-items:flex-start}}@media(max-width:600px){.profile-strip{flex-direction:column;gap:10px}.discovery-workspace>.title-row{align-items:flex-start;gap:14px;flex-direction:column}.candidate-toolbar{gap:12px}.candidate-toolbar h2{width:100%}.candidate-toolbar select{max-width:140px}.candidate-card{padding:16px}}
</style>
